<?php
require_once __DIR__.'/config/app.php';require_customer();$cartId=get_or_create_cart((int)current_user()['id']);$stmt=db()->prepare('SELECT ci.id item_id,ci.quantity,p.*,(ci.quantity*p.price) line_total,c.name category_name FROM cart_items ci JOIN products p ON p.id=ci.product_id JOIN categories c ON c.id=p.category_id WHERE ci.cart_id=? ORDER BY ci.created_at DESC');$stmt->execute([$cartId]);$items=$stmt->fetchAll();$subtotal=array_sum(array_column($items,'line_total'));$pageTitle='Keranjang';$extraJs='cart.js';require APP_ROOT.'/includes/header.php';
?>
<section class="page-hero"><div class="container"><div class="d-flex align-items-end justify-content-between gap-3"><div><div class="section-kicker">Keranjang belanja</div><h1>Produk pilihan Anda</h1></div><?php if($items):?><form action="<?= url('actions/cart-clear.php') ?>" method="post"><?= csrf_field() ?><button class="btn btn-outline-danger" data-confirm="Kosongkan seluruh keranjang?"><i class="bi bi-trash me-1"></i>Kosongkan</button></form><?php endif;?></div></div></section><section class="pb-5"><div class="container"><?php if(!$items):?><div class="content-card empty-state"><i class="bi bi-bag-x"></i><h3 class="fw-bold mt-3">Keranjang masih kosong</h3><p class="text-muted">Temukan produk menarik dan tambahkan ke keranjang.</p><a class="btn btn-primary" href="<?= url('shop.php') ?>">Mulai Belanja</a></div><?php else:?><div class="row g-4"><div class="col-lg-8"><div class="content-card p-0 overflow-hidden"><?php foreach($items as $item):?><div class="p-3 p-md-4 border-bottom"><div class="row align-items-center g-3"><div class="col-3 col-md-2"><img class="w-100 rounded-3" style="aspect-ratio:1;object-fit:cover" src="<?= e(product_image($item['image'])) ?>" alt=""></div><div class="col-9 col-md-4"><div class="small text-muted"><?= e($item['category_name']) ?></div><a class="fw-bold text-dark" href="<?= url('product.php?id='.$item['id']) ?>"><?= e($item['name']) ?></a><div class="text-primary fw-bold"><?= rupiah($item['price']) ?></div></div><div class="col-7 col-md-3"><form action="<?= url('actions/cart-update.php') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="item_id" value="<?= $item['item_id'] ?>"><div class="d-flex gap-2"><input class="form-control" type="number" name="quantity" min="1" max="<?= $item['stock'] ?>" value="<?= $item['quantity'] ?>"><button class="btn btn-light-green"><i class="bi bi-arrow-repeat"></i></button></div></form><small class="text-muted">Stok: <?= $item['stock'] ?></small></div><div class="col-5 col-md-3 text-end"><div class="fw-bold mb-2"><?= rupiah($item['line_total']) ?></div><form action="<?= url('actions/cart-remove.php') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="item_id" value="<?= $item['item_id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Hapus produk dari keranjang?"><i class="bi bi-trash"></i></button></form></div></div></div><?php endforeach;?></div></div><div class="col-lg-4"><div class="summary-card"><h5 class="fw-bold">Ringkasan belanja</h5><div class="d-flex justify-content-between py-3 border-bottom"><span class="text-muted">Jumlah barang</span><strong><?= cart_count() ?></strong></div><div class="d-flex justify-content-between py-3"><span>Subtotal</span><strong class="text-primary fs-5"><?= rupiah($subtotal) ?></strong></div><p class="small text-muted"><i class="bi bi-info-circle me-1"></i>Ongkir ditampilkan pada halaman checkout.</p><a class="btn btn-primary w-100 py-3" href="<?= url('checkout.php') ?>">Lanjut Checkout <i class="bi bi-arrow-right"></i></a><a class="btn btn-light w-100 mt-2" href="<?= url('shop.php') ?>">Lanjut Belanja</a></div></div></div><?php endif;?></div></section>
